import{_ as s,o as e,c as n,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"91. Designing Small C Libraries","description":"The Little Book of C — 91. Designing Small C Libraries","frontmatter":{"title":"91. Designing Small C Libraries","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Building Real Projects"],"description":"The Little Book of C — 91. Designing Small C Libraries","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":91,"sidebarWeight":91,"lang":"en-US","alternateEn":"/posts/c教程/en-US/10-Building Real Projects/091-Designing Small C Libraries","alternateZh":"/posts/c教程/zh-CN/10-真实项目/091-Designing Small C Libraries"},"headers":[],"relativePath":"posts/c教程/en-US/10-Building Real Projects/091-Designing Small C Libraries.md","filePath":"posts/c教程/en-US/10-Building Real Projects/091-Designing Small C Libraries.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/10-Building Real Projects/091-Designing Small C Libraries.md"};function l(p,a,r,o,d,c){return e(),n("div",null,[...a[0]||(a[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/10-真实项目/091-Designing Small C Libraries)</p><p>Writing libraries is how you make your C code reusable, modular, and easy to maintain. In this section, you’ll learn how to design and structure a small, portable, and well-documented C library, the kind used in real systems for decades.</p><h4 id="step-1-what-is-a-library-in-c" tabindex="-1">Step 1. What Is a Library in C? <a class="header-anchor" href="#step-1-what-is-a-library-in-c" aria-label="Permalink to &quot;Step 1. What Is a Library in C?&quot;">​</a></h4><p>A library in C is a collection of functions and data types that can be used by multiple programs.</p><p>There are two kinds of libraries:</p><ul><li>Static libraries (<code>.a</code> or<code>.lib</code>) – compiled into the final program at build time.</li><li>Shared libraries (<code>.so</code> or<code>.dll</code>) – loaded dynamically at runtime.</li></ul><p>You’ll start by building a small static library that provides reusable math utilities.</p><h4 id="step-2-plan-the-library" tabindex="-1">Step 2. Plan the Library <a class="header-anchor" href="#step-2-plan-the-library" aria-label="Permalink to &quot;Step 2. Plan the Library&quot;">​</a></h4><p>Let’s design a library called simplemath, which provides:</p><ul><li><code>add</code>,<code>subtract</code>,<code>multiply</code>,<code>divide</code></li><li>Error handling for divide-by-zero</li><li>Clean, consistent naming</li></ul><p>Structure:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>simplemath/</span></span>
<span class="line"><span> ├── include/</span></span>
<span class="line"><span> │    └── simplemath.h</span></span>
<span class="line"><span> ├── src/</span></span>
<span class="line"><span> │    └── simplemath.c</span></span>
<span class="line"><span> └── Makefile</span></span></code></pre></div><h4 id="step-3-the-header-file-simplemath-h" tabindex="-1">Step 3. The Header File (simplemath.h) <a class="header-anchor" href="#step-3-the-header-file-simplemath-h" aria-label="Permalink to &quot;Step 3. The Header File (simplemath.h)&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef SIMPLEMATH_H</span></span>
<span class="line"><span>#define SIMPLEMATH_H</span></span>
<span class="line"><span>#ifdef __cplusplus</span></span>
<span class="line"><span>extern &quot;C&quot; {</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>double sm_add(double a, double b);</span></span>
<span class="line"><span>double sm_sub(double a, double b);</span></span>
<span class="line"><span>double sm_mul(double a, double b);</span></span>
<span class="line"><span>double sm_div(double a, double b, int *error);</span></span>
<span class="line"><span>#ifdef __cplusplus</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>Notes:</p><ul><li>Include guards prevent double inclusion.</li><li><code>extern &quot;C&quot;</code> allows usage in C++ projects.</li><li>Prefix (<code>sm_</code>) prevents naming conflicts.</li></ul><h4 id="step-4-the-implementation-file-simplemath-c" tabindex="-1">Step 4. The Implementation File (simplemath.c) <a class="header-anchor" href="#step-4-the-implementation-file-simplemath-c" aria-label="Permalink to &quot;Step 4. The Implementation File (simplemath.c)&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;simplemath.h&quot;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>double sm_add(double a, double b) { return a + b; }</span></span>
<span class="line"><span>double sm_sub(double a, double b) { return a - b; }</span></span>
<span class="line"><span>double sm_mul(double a, double b) { return a * b; }</span></span>
<span class="line"><span>double sm_div(double a, double b, int *error) {</span></span>
<span class="line"><span>    if (b == 0) {</span></span>
<span class="line"><span>        if (error) *error = 1;</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Division by zero\\n&quot;);</span></span>
<span class="line"><span>        return 0.0;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    if (error) *error = 0;</span></span>
<span class="line"><span>    return a / b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="step-5-tiny-code-example-program-using-the-library" tabindex="-1">Step 5. Tiny Code: Example Program Using the Library <a class="header-anchor" href="#step-5-tiny-code-example-program-using-the-library" aria-label="Permalink to &quot;Step 5. Tiny Code: Example Program Using the Library&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;simplemath.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int err;</span></span>
<span class="line"><span>    double x = sm_div(10, 2, &amp;err);</span></span>
<span class="line"><span>    printf(&quot;10 / 2 = %.2f\\n&quot;, x);</span></span>
<span class="line"><span>    x = sm_div(10, 0, &amp;err);</span></span>
<span class="line"><span>    if (err) printf(&quot;Error detected during division.\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="step-6-makefile-to-build-the-library" tabindex="-1">Step 6. Makefile to Build the Library <a class="header-anchor" href="#step-6-makefile-to-build-the-library" aria-label="Permalink to &quot;Step 6. Makefile to Build the Library&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -std=c23 -O2 -Wall -Wextra -Iinclude</span></span>
<span class="line"><span>all: libsimplemath.a test</span></span>
<span class="line"><span>libsimplemath.a: src/simplemath.o</span></span>
<span class="line"><span>    ar rcs libsimplemath.a src/simplemath.o</span></span>
<span class="line"><span>src/simplemath.o: src/simplemath.c include/simplemath.h</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c src/simplemath.c -o src/simplemath.o</span></span>
<span class="line"><span>test: test.c libsimplemath.a</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) test.c -L. -lsimplemath -o test</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f src/*.o *.a test</span></span></code></pre></div><p>Build it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./test</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10 / 2 = 5.00</span></span>
<span class="line"><span>Division by zero</span></span>
<span class="line"><span>Error detected during division.</span></span></code></pre></div><h4 id="step-7-design-guidelines-for-clean-c-libraries" tabindex="-1">Step 7. Design Guidelines for Clean C Libraries <a class="header-anchor" href="#step-7-design-guidelines-for-clean-c-libraries" aria-label="Permalink to &quot;Step 7. Design Guidelines for Clean C Libraries&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Principle</th><th>Description</th></tr></thead><tbody><tr><td>Prefix all symbols</td><td>Avoid global name clashes (e.g.,<code>sm_add</code>)</td></tr><tr><td>Single responsibility</td><td>Each function should do one clear thing</td></tr><tr><td>Minimal dependencies</td><td>Don’t rely on non-standard headers</td></tr><tr><td>Use header guards</td><td>Prevent duplicate inclusion</td></tr><tr><td>Provide error handling</td><td>Return codes,<code>errno</code>, or out parameters</td></tr><tr><td>Write documentation</td><td>Use Doxygen or simple comment blocks</td></tr><tr><td>Version your API</td><td>Track breaking changes cleanly</td></tr></tbody></table><h4 id="step-8-adding-versioning-and-metadata" tabindex="-1">Step 8. Adding Versioning and Metadata <a class="header-anchor" href="#step-8-adding-versioning-and-metadata" aria-label="Permalink to &quot;Step 8. Adding Versioning and Metadata&quot;">​</a></h4><p>Add this to your header:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define SIMPLEMATH_VERSION &quot;1.0.0&quot;</span></span></code></pre></div><p>In your CMake or Makefile build scripts, you can propagate this version into your packaging system or documentation.</p><h4 id="step-9-why-it-matters" tabindex="-1">Step 9. Why It Matters <a class="header-anchor" href="#step-9-why-it-matters" aria-label="Permalink to &quot;Step 9. Why It Matters&quot;">​</a></h4><p>Writing a library transforms you from a script author into a systems builder. It teaches API design, separation of interface and implementation, and long-term maintenance, the same principles used in real-world software like glibc, SQLite, and curl.</p><h4 id="step-10-try-it-yourself" tabindex="-1">Step 10. Try It Yourself <a class="header-anchor" href="#step-10-try-it-yourself" aria-label="Permalink to &quot;Step 10. Try It Yourself&quot;">​</a></h4><ol><li>Add new functions (<code>sm_pow</code>,<code>sm_mod</code>,<code>sm_avg</code>).</li><li>Create a shared version of the library (<code>libsimplemath.so</code>).</li><li>Document your API using Doxygen-style comments.</li><li>Write a header-only version (<code>static inline</code> functions).</li><li>Package your library with versioning and examples.</li></ol><p>Next, you’ll learn how to build a full command-line tool in C (92), connecting your reusable libraries to practical, user-facing applications.</p>`,39)])])}const m=s(t,[["render",l]]);export{u as __pageData,m as default};
